const now = new Date().toISOString();
return [{ json: {
  schema_version: '1.0.0',
  run_id: `RUN-T1-${Date.now()}`,
  test_id: 'T1',
  input_type: 'evaluation_test',
  source_name: 'eval_prdgenie_inputs.txt',
  source_text: 'The user should be able to filter reports by date range, category, and status. Results must load in under 2 seconds. PM: Sarah. Deadline: Q3.',
  submitted_by: 'Capstone evaluator',
  submitted_at: now,
  metadata: { meeting_date: null, document_version: 'baseline-v1', language: 'en' }
} }];

const data = $json;
const errors = [];
if (data.schema_version !== '1.0.0') errors.push('schema_version must be 1.0.0');
if (!/^RUN-[A-Za-z0-9-]+$/.test(data.run_id || '')) errors.push('run_id is invalid');
if (!['meeting_transcript','product_brief','stakeholder_notes','evaluation_test'].includes(data.input_type)) errors.push('input_type is invalid');
if (!(data.source_name || '').trim()) errors.push('source_name is required');
if (!(data.source_text || '').trim()) errors.push('source_text is required');
if (Number.isNaN(Date.parse(data.submitted_at))) errors.push('submitted_at must be an ISO date-time');
if (errors.length) throw new Error(`Workflow input validation failed: ${errors.join('; ')}`);
return [{ json: data }];

