const raw = $json.text ?? $json.output ?? $json.response;
if (typeof raw !== 'string') throw new Error('Extractor response did not contain a text payload');
const cleaned = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
let result;
try { result = JSON.parse(cleaned); } catch (error) { throw new Error(`Extractor returned invalid JSON: ${error.message}`); }
const errors = [];
const required = ['schema_version','run_id','extraction_status','summary','items','contradictions','missing_information'];
for (const field of required) if (!(field in result)) errors.push(`missing ${field}`);
if (result.schema_version !== '1.0.0') errors.push('schema_version must be 1.0.0');
if (!['complete','partial','no_requirements'].includes(result.extraction_status)) errors.push('invalid extraction_status');
if (!Array.isArray(result.items)) errors.push('items must be an array');
if (!Array.isArray(result.contradictions)) errors.push('contradictions must be an array');
if (!Array.isArray(result.missing_information)) errors.push('missing_information must be an array');
if (Array.isArray(result.items)) {
  for (const [index, item] of result.items.entries()) {
    if (!item.id || !item.type || !item.statement || !item.status) errors.push(`item ${index} missing required identity fields`);
    if (!Array.isArray(item.evidence) || item.evidence.length === 0) errors.push(`item ${item.id || index} has no evidence`);
    for (const evidence of item.evidence || []) if (!evidence.quote || !evidence.source_name || !evidence.location) errors.push(`item ${item.id || index} has incomplete evidence`);
  }
}
if (result.extraction_status === 'no_requirements' && result.items.length !== 0) errors.push('no_requirements must have an empty items array');
if (errors.length) throw new Error(`Extraction validation failed: ${errors.join('; ')}`);
return [{ json: { extraction: result, validation: { schema_version: '1.0.0', structurally_valid: true, validated_at: new Date().toISOString() } } }];
